 "content": "def transform(grid):
    """Stamp the edge sequence containing each isolated marker's color."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Multi-cell contiguous runs along the top/bottom borders are templates.
    templates = []
    source_cells = set()
    for r in sorted({0, h - 1}):
        c = 0
        while c < w:
            if grid[r][c] == 0:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] != 0:
                c += 1
            if c - start >= 2:
                seq = grid[r][start:c]
                templates.append(seq)
                source_cells.update((r, x) for x in range(start, c))

    # For each non-source colored cell, align the matching template color
    # under that cell and stamp the full sequence, clipping at grid edges.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in source_cells:
                continue
            matches = [(seq, i) for seq in templates for i, x in enumerate(seq) if x == color]
            if not matches:
                continue
            # A marker's color normally identifies one template; if shared,
            # use the first edge template containing it.
            seq, i = matches[0]
            start = c - i
            for j, x in enumerate(seq):
                cc = start + j
                if 0 <= cc < w:
                    out[r][cc] = x
    return out
